        'help' => [
            'button' => 'Help',
            'index' => [
                'title' => 'About supplier follow-up',
                'intro_title' => 'What is the page for?',
                'intro' => 'The supplier register: here you find, register and open the suppliers the organisation depends on. What needs doing for each supplier is shown on the supplier page, and your tasks are under Follow-up.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Find a supplier', 'text' => 'Type a name or organisation number in «Search», optionally choose «Status», «Category» and «Criticality», and choose «Search». «Reset» clears the filters. Ended suppliers are shown when you choose «All statuses».'],
                            ['title' => '2. Register or import suppliers', 'text' => 'Choose «Register supplier» to add one supplier, or «Import suppliers» to add many from an Excel file.'],
                            ['title' => '3. Open a supplier', 'text' => 'Choose the supplier\'s name. The supplier page has the tabs «Overview», «Requirements and qualifications», «Documentation», «Assessments», «Due diligence» and «History».'],
                            ['title' => '4. Fill in the profile and assess criticality', 'text' => 'On the «Overview» tab, choose «Assess criticality» to set Standard, Important or Critical, and «Fill in profile» to describe the delivery. The profile decides which control requirements apply.'],
                            ['title' => '5. Carry out a supplier assessment', 'text' => 'Open the «Assessments» tab and choose «Assess supplier». Assess the four areas and choose the overall assessment.'],
                            ['title' => '6. Assess the control requirements', 'text' => 'Register the documentation under the «Documentation» tab. Then open the «Requirements and qualifications» tab and choose «Control requirement» on each requirement to be assessed.'],
                            ['title' => '7. See what needs follow-up', 'text' => 'In the list, «Needs follow-up» appears under the name of suppliers that have something to follow up, with what it concerns. Tick «Only suppliers that need follow-up» and choose «Search» to see only those. On the supplier page, «Needs follow-up» is on the «Overview» tab, with each point and a link to the right tab. Suppliers you are the internal owner of also appear as tasks under Follow-up in the left menu.'],
                            ['title' => '8. See deleted suppliers', 'text' => 'If you have the right to delete suppliers, choose «Deleted suppliers» at the top right. It lists which suppliers have been deleted, when and by whom. The log cannot be changed.'],
                        ],
                    ],
                    [
                        'title' => 'The suppliers',
                        'items' => [
                            ['title' => 'One supplier, once', 'text' => 'Each supplier is registered once, as the company it is – not once per contract, service or document. If it delivers several things, describe them in «What do they deliver to us?».'],
                            ['title' => 'Internal owner', 'text' => 'Each supplier has a person in your organisation who follows it up. Ownership grants no extra access.'],
                            ['title' => 'Category', 'text' => 'The category makes the register easier to filter. Choose the one that fits best.'],
                        ],
                    ],
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Under review', 'text' => 'Registered, but not taken into use.'],
                            ['title' => 'Active', 'text' => 'The supplier is in use.'],
                            ['title' => 'Ended', 'text' => 'The supplier is no longer in use, or was not chosen. Ended suppliers are shown when you choose «All statuses» or «Ended».'],
                        ],
                    ],
                    [
                        'title' => 'Criticality',
                        'items' => [
                            ['title' => 'Standard, Important or Critical', 'text' => 'Criticality says how important the supplier is to the organisation. You choose the level yourselves; four yes/no questions are the basis for the choice, but are not turned into any level.'],
                            ['title' => 'Not assessed', 'text' => 'The supplier has no criticality yet. Open the supplier and choose «Assess criticality».'],
                        ],
                    ],
                    [
                        'title' => 'Needs follow-up',
                        'items' => [
                            ['title' => 'When is the marker shown?', 'text' => 'When the supplier is not ended and has something concrete to follow up: an active Important or Critical supplier without a supplier assessment, a supplier assessment that is overdue, no internal owner, or documentation that has expired or expires within 60 days. With control requirements, also: mandatory requirements that are not documented or temporarily accepted, control overdue, mandatory or important requirements not controlled, important or critical suppliers without a filled-in profile, due diligence assessments that are missing or overdue, and suppliers whose need for due diligence must be clarified in the profile.'],
                            ['title' => 'Only the supplier\'s own information', 'text' => 'The marker is based only on what is registered here. Risks, requirements and cases in other modules do not affect it. Once the supplier is followed up, the marker disappears.'],
                            ['title' => 'Where it is followed up', 'text' => 'The list only shows what it concerns. The supplier page explains each point and has the actions. Under Follow-up, the internal owner gets one task per supplier with all the points together – not one task per requirement.'],
                            ['title' => 'Requirement status', 'text' => 'The column shows whether the control requirements that apply to the supplier are In order, Need follow-up or have a mandatory requirement open. It is a fact about the requirements, not an approval: the system never approves a supplier.'],
                        ],
                    ],
                    [
                        'title' => 'Access',
                        'items' => [
                            ['title' => 'Permissions', 'text' => 'Who can view, register and delete suppliers is decided by the roles under Access in the customer environment.'],
                            ['title' => 'System Owner', 'text' => 'System Owner does not get access automatically. To work here, give yourself a role with the permissions.'],
                        ],
                    ],
                ],
            ],
            'control_requirements' => [
                'title' => 'About control requirements',
                'intro_title' => 'What is the page for?',
                'intro' => 'Here you define and maintain your organisation\'s control requirements – the requirements you set for suppliers. Which of them apply to one supplier, and how they have been controlled, is on the supplier\'s «Requirements and qualifications» tab. Requirement templates are optional suggestions for new control requirements.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Open Control requirements', 'text' => 'Choose Governance → Suppliers in the left menu, and then the «Control requirements» tab at the top of the page.'],
                            ['title' => '2. See your control requirements', 'text' => 'Under «Your control requirements» are the requirements you have taken into use, grouped by theme. Each requirement shows its level, when it applies, how many suppliers it applies to now, and when and how often it is controlled.'],
                            ['title' => '3. See what a template contains', 'text' => 'Choose the «Requirement templates» heading at the bottom of the page to open the section. Then choose «Show the requirements» on a template. You see the code, title, theme and level of each requirement, and whether it is already in use. Choose «Hide the requirements» to close the list. Looking at the requirements changes nothing.'],
                            ['title' => '4. Use a requirement template', 'text' => 'Choose «Use requirement template». The confirmation shows which requirements are added and which are already there. Choose «Add … control requirements» to add them.'],
                            ['title' => '5. Create your own control requirement', 'text' => 'Choose «New control requirement», fill in the title, theme, level, when and how often the requirement is controlled, and which suppliers it applies to. Choose «Save control requirement».'],
                            ['title' => '6. Change a requirement', 'text' => 'Choose «Edit» on the requirement. «Mark as retired» makes the requirement apply to no supplier, and «Use again» makes it apply again. «Delete» is offered only for requirements that have never been used or retired. «Change history» on the requirement shows when it was retired or used again, and by whom.'],
                            ['title' => '7. Find the requirements for a supplier', 'text' => 'Open the supplier from the «Suppliers» tab, and choose the «Requirements and qualifications» tab. Under «Control requirements for the supplier» it lists the requirements that apply to the supplier, and why. With «Add requirement» and «Does not apply to this supplier» you override with a reason. A requirement for one supplier only is created and maintained on the supplier.'],
                            ['title' => '8. Document the control', 'text' => 'Register the documentation under the «Documentation» tab. Then choose «Control requirement» on the requirement, and choose the documentation you relied on, the result and the reason. Requirement status at the top of the tab shows how many requirements are documented and which mandatory requirements are open.'],
                            ['title' => '9. Permissions', 'text' => 'Everyone with access to Suppliers can see the control requirements and the templates. Creating and changing control requirements, using templates, overriding and controlling requirements require the «Carry out supplier control» permission. It is given in a role under Customer environment → Permissions.'],
                        ],
                    ],
                    [
                        'title' => 'Which suppliers a requirement applies to',
                        'items' => [
                            ['title' => 'All or some', 'text' => 'A requirement applies to all suppliers, or to suppliers where at least one of the conditions you choose applies according to the supplier profile. You can also limit it to important and critical suppliers.'],
                            ['title' => 'Not clarified', 'text' => 'If a condition is «Not clarified» in the profile, the requirement applies. If the profile has not been filled in at all, only requirements that follow from the criticality apply.'],
                        ],
                    ],
                    [
                        'title' => 'Requirement level',
                        'items' => [
                            ['title' => 'Mandatory, Important or Follow-up', 'text' => 'Mandatory requirements cannot be excluded for a single supplier. If a mandatory requirement applies wrongly, correct the profile or the requirement.'],
                        ],
                    ],
                    [
                        'title' => 'Changing and retiring',
                        'items' => [
                            ['title' => 'Mark as retired', 'text' => 'A retired requirement applies to no supplier. Manual decisions and history are kept, and the change is recorded in the requirement\'s «Change history» with time and who did it. That history cannot be changed or deleted. A requirement that has never been used or retired can be deleted.'],
                            ['title' => 'Anchor', 'text' => 'A requirement can be anchored in a requirement in Compliance and audit. The anchor is optional and shown only to people with access there. The basis is always written in the requirement itself.'],
                            ['title' => 'Access', 'text' => 'Everyone with access to Supplier management can see the requirements. Only roles with the supplier assurance permission can change them.'],
                        ],
                    ],
                    [
                        'title' => 'Requirement templates',
                        'items' => [
                            ['title' => 'A starting point', 'text' => 'The templates are starting points for different types of supplier, and you can use several of them. A template adds the control requirements you do not already have. A requirement that is already there – also from another template – is not added again, and your own requirements are not changed.'],
                            ['title' => 'The requirements are yours', 'text' => 'Requirements from a template can be edited, retired or deleted like any other control requirement. A newer version of the template does not change them.'],
                            ['title' => 'Typical basis', 'text' => 'The templates describe typical supplier requirements, not a legal answer. Assess them against your own agreements and obligations. The requirements must still be controlled, and the assessments are made by people.'],
                        ],
                    ],
                ],
            ],
            'supplier' => [
                'title' => 'About the supplier',
                'intro_title' => 'What is the page for?',
                'intro' => 'The supplier page brings together what you know about the supplier, what is missing, and what needs doing next. Here you follow up the requirements, the documentation and the assessments of the supplier.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. See what needs follow-up', 'text' => 'The «Overview» tab opens first. At the top, «Needs follow-up» lists each point with a link, for example «Go to Requirements and qualifications», that takes you to the right tab. If nothing is listed there, that does not mean the supplier is approved.'],
                            ['title' => '2. Find the facts about the supplier', 'text' => '«About the supplier» shows what the supplier delivers, category, internal owner, contact person and «Next control». Choose «Show all controls» to see every deadline, and «Edit» at the top right to change the facts.'],
                            ['title' => '3. Open the details, assess criticality and fill in the profile', 'text' => 'Under «Details», choose a heading to open or close it: «Supplier information», «Criticality», «Supplier profile», «Risks» and «Deviations and improvements». Under «Criticality» choose «Assess criticality», and under «Supplier profile» «Fill in profile». The profile and the criticality decide which control requirements apply.'],
                            ['title' => '4. Register the documentation and control the requirements', 'text' => 'Open the «Documentation» tab and choose «Add documentation». Then open the «Requirements and qualifications» tab and choose «Control requirement» on each requirement, with the documentation you relied on, the result and the reason. If the supplier needs a requirement that does not apply automatically, choose «Add requirement».'],
                            ['title' => '5. Assess the supplier', 'text' => 'Open the «Assessments» tab and choose «Assess supplier». The supplier assessment concerns how the supplier delivers, and is separate from the control of the requirements. Due diligence assessments are registered on the «Due diligence» tab when it is shown.'],
                            ['title' => '6. Take into use, end or reopen', 'text' => 'At the bottom of «Overview», under «Other actions», are «Take into use», «End supplier» or «Reopen supplier», and «Create knowledge article» to share knowledge with the Wiki. If a mandatory requirement is open, you are warned before the supplier is taken into use, but you can choose «Start using anyway».'],
                        ],
                    ],
                    [
                        'title' => 'How the page is organised',
                        'items' => [
                            ['title' => 'Overview', 'text' => 'Overview is short: «Needs follow-up», «About the supplier» with the next control, «Details» that stay closed until you open them, and «Other actions» at the bottom. Criticality and status are next to the supplier name at the top.'],
                            ['title' => 'The tabs', 'text' => 'Requirements and qualifications, Documentation, Assessments and Due diligence hold the lists, the history and the actions. The links in «Needs follow-up» and «Next control» open the right tab.'],
                            ['title' => 'History', 'text' => 'The «History» tab shows status changes, criticality changes and the profile history, with date, who and reason. If the supplier has control decisions from before registering such decisions was discontinued, they are listed there as earlier control decisions. The same goes for «Earlier links to compliance requirements».'],
                        ],
                    ],
                    [
                        'title' => 'Security and privacy',
                        'items' => [
                            ['title' => 'What the card shows', 'text' => 'At the top of the «Requirements and qualifications» tab: the profile facts that make security, privacy and continuity requirements apply – personal data, access, where the data is processed and subcontractors – and the status of each of those requirements now.'],
                            ['title' => 'No overall rating', 'text' => 'The card is an extract of the requirements. It gives no points or overall status, and it does not approve the supplier.'],
                            ['title' => 'Requirement templates', 'text' => 'The requirements come from your control requirements, often from a requirement template. Templates are applied under Control requirements; each requirement\'s level is changed there.'],
                        ],
                    ],
                    [
                        'title' => 'From registered to ended',
                        'items' => [
                            ['title' => 'Take into use', 'text' => 'A supplier under review becomes active when you take it into use.'],
                            ['title' => 'End supplier', 'text' => 'When the supplier is no longer in use, or was not chosen, end it with a reason. The supplier can then not be changed, but everything registered stays.'],
                            ['title' => 'Reopen supplier', 'text' => 'An ended supplier can be reopened with a reason. It becomes active again and can be changed.'],
                        ],
                    ],
                    [
                        'title' => 'Criticality',
                        'items' => [
                            ['title' => 'How important is the supplier?', 'text' => 'Choose Standard, Important or Critical. The four yes/no questions are the basis for the choice and are saved with it, but the system neither calculates nor suggests a level.'],
                            ['title' => 'Review interval', 'text' => 'How often the supplier should be reviewed. Important and critical suppliers must have an interval.'],
                            ['title' => 'Change criticality', 'text' => 'Every change requires a reason and is saved in the history with the level, interval and answers before and after. The history cannot be changed or deleted.'],
                        ],
                    ],
                    [
                        'title' => 'Supplier profile',
                        'items' => [
                            ['title' => 'What the profile is', 'text' => 'The profile describes the circumstances of the delivery – data, access, supply chain, work and contract terms. It will later decide which control requirements apply to the supplier. It is not an assessment of the supplier.'],
                            ['title' => 'Yes, No or Not clarified', 'text' => 'Choose «Not clarified» when you do not know the answer yet. It is not the same as «No»: something not clarified is treated as if it applies.'],
                            ['title' => 'Changing the profile', 'text' => 'Filling it in the first time needs no reason. Later changes require a reason and are saved in the profile history with the answers before and after. The history cannot be changed or deleted.'],
                        ],
                    ],
                    [
                        'title' => 'Requirements and qualifications',
                        'items' => [
                            ['title' => 'Which requirements apply?', 'text' => 'The control requirements normally come automatically from the supplier profile and the criticality, and are worked out every time the page is opened. When the profile or the criticality changes, the requirements change at once.'],
                            ['title' => 'Applies because …', 'text' => 'Each requirement shows why it applies. A condition that is «Not clarified» in the profile counts as applying, and the reason then says it is not clarified.'],
                            ['title' => 'Add requirement', 'text' => 'With the supplier assurance permission you choose «Add requirement» and then «Choose an existing control requirement» for a requirement from Control requirements that does not apply automatically, or «Create a requirement for this supplier» for a requirement that should apply to this supplier only. Adding an existing requirement needs a reason and is kept in the history.'],
                            ['title' => 'Excluding a requirement', 'text' => '«Does not apply to this supplier» excludes a requirement that applies automatically, with a reason. Mandatory requirements cannot be excluded. «Back to automatic assessment» lifts the decision.'],
                            ['title' => 'Requirements for this supplier only', 'text' => 'A requirement created for this supplier is changed with «Edit requirement» on the requirement. When it no longer applies, choose «Mark as retired». The requirement then moves to «Retired control requirements» at the bottom of the section, with its controls. There you can choose «Use again» – it is the same requirement, not a copy, and earlier controls stay. «Change history» on the requirement shows each time it was retired or used again, with time and who did it, apart from the controls. The requirement is not listed under Control requirements and applies to no other supplier.'],
                            ['title' => 'Anchored in', 'text' => '«Anchored in» shows which requirement in Compliance and audit the control requirement comes from. It does not say the requirement is met – the control of the requirement shows that.'],
                            ['title' => 'Documentation is the basis', 'text' => 'When you control a requirement, you choose the documentation you relied on. Documentation is registered under Documentation. Choosing a document does not mean the requirement is met.'],
                            ['title' => 'The controller judges', 'text' => 'You decide whether the documentation covers the requirement: Documented, Partially documented, Missing or Temporarily accepted until a date. The system never sets the result itself. «Documented» needs at least one document, and every result needs a reason.'],
                            ['title' => 'The history does not change', 'text' => 'A control cannot be changed or deleted. If it is wrong, register a new one. The control shows the documentation as it was registered then, even if the document changes later. «Renewal due» shows when the control interval has passed or the document has now expired or been replaced.'],
                        ],
                    ],
                    [
                        'title' => 'Requirement status',
                        'items' => [
                            ['title' => 'What requirement status shows', 'text' => 'The control state is computed from the requirements that apply and their controls each time the page opens: how many requirements apply, how many are documented, missing or overdue, and whether a mandatory requirement is open. It is not stored.'],
                            ['title' => 'Mandatory requirement open', 'text' => 'When a mandatory requirement is neither documented nor temporarily accepted, it is shown under Requirement status and under Needs follow-up. It goes away only when the requirement is documented or temporarily accepted.'],
                            ['title' => 'Facts, not judgement', 'text' => 'Requirement status says what the controls show. The result of each control – Documented, Partially documented, Missing or Temporarily accepted – is set by the person controlling, always with a rationale.'],
                            ['title' => 'The system never approves by itself', 'text' => 'The system never approves or rejects a supplier, not even when everything is documented. Overall control decisions are no longer registered; decisions registered before are kept as history on the «History» tab.'],
                        ],
                    ],
                    [
                        'title' => 'Follow-up',
                        'items' => [
                            ['title' => 'Upcoming controls', 'text' => 'Procynia calculates when each control requirement should be controlled again: the last control plus the requirement\'s control interval. Requirements without an interval get no fixed date. Documentation used in a control, and temporary acceptance, have dates of their own.'],
                            ['title' => 'Needs follow-up', 'text' => 'Open mandatory requirements, overdue controls, documents that must be renewed, expired temporary acceptances and requirements not controlled are shown under Needs follow-up. A requirement is named once; if a mandatory requirement is open, it is named there.'],
                            ['title' => 'Nothing happens automatically', 'text' => 'The system never registers a control when a date passes. Requirement status shows what needs follow-up.'],
                            ['title' => 'Follow up in Deviations and improvements', 'text' => 'A control that is not documented can be followed up as a case in Deviations and improvements. The case does not change the requirement status – it is follow-up, not acceptance.'],
                        ],
                    ],
                    [
                        'title' => 'Due diligence and sustainability',
                        'items' => [
                            ['title' => 'What due diligence is', 'text' => 'Mapping, assessing, investigating and following up the risk of breaches of human rights, working conditions and the environment in the supply chain.'],
                            ['title' => 'Six areas, no overall score', 'text' => 'Child labour, forced labour, working conditions, discrimination, freedom of association and environment are assessed one by one: Low, Elevated, High or Unknown. Unknown means it has not been clarified, not that the risk is low. The system does not calculate any overall risk.'],
                            ['title' => 'A person concludes', 'text' => 'You choose the conclusion and give the rationale. The assessment never approves or rejects the supplier, and does not change the criticality.'],
                            ['title' => 'When is it required?', 'text' => 'When the profile confirms that the goods are in a high-risk category, that production or work takes place outside Norway/the EEA, or that the delivery is labour-intensive and uses subcontractors. These are Procynia\'s criteria for follow-up – not an assessment of your organisation\'s legal obligations.'],
                            ['title' => 'The need for due diligence must be clarified', 'text' => 'When an answer that could trigger the assessment is «Not clarified» or not answered, and nothing else already makes it required. Missing information does not mean an assessment is required – only that Procynia cannot conclude yet. The page says which information it concerns; choose «Go to supplier profile» and clarify it. An unclarified answer that cannot change the conclusion does not prevent «Not required».'],
                            ['title' => 'Voluntary assessment', 'text' => 'You can register a due diligence assessment whatever the status, also when it is not required or must be clarified.'],
                            ['title' => 'Need and result are two things', 'text' => 'The status says whether an assessment is required. Whether one has been carried out, and what it concluded, is under «Due diligence assessments». A supplier can be «required» and have a completed assessment.'],
                            ['title' => 'Follow up the findings', 'text' => 'With «Measures required» you can follow up in Deviations and improvements. A significant risk to the business can be registered in Risk. A new assessment falls due after the interval you choose.'],
                            ['title' => 'History is not changed', 'text' => 'A due diligence assessment cannot be changed or deleted. Register a new assessment instead.'],
                        ],
                    ],
                    [
                        'title' => 'Supplier assessment',
                        'items' => [
                            ['title' => 'How does the supplier perform?', 'text' => 'Rate quality, delivery precision, information security and compliance, then choose the overall assessment yourself. The system calculates no result.'],
                            ['title' => 'Next review', 'text' => 'The latest assessment plus the supplier\'s review interval. Without an interval or an assessment there is no next date.'],
                            ['title' => 'A mistake in an assessment?', 'text' => 'An assessment cannot be changed or deleted. Register a new assessment instead.'],
                        ],
                    ],
                    [
                        'title' => 'Documentation',
                        'items' => [
                            ['title' => 'What is registered', 'text' => 'Which documentation exists – agreements, data processing agreements, certificates, certificates of insurance and the like – where it is kept, and when it expires. The document itself is not uploaded; it stays where you archive it.'],
                            ['title' => 'Not in the Wiki', 'text' => 'The supplier\'s contracts, certificates and agreements are not put in the Wiki. The Wiki is for knowledge you reuse, not an archive for one supplier\'s documents.'],
                            ['title' => 'Register renewed', 'text' => 'When you receive a new edition, register it as renewed. The previous one stays and is shown as replaced.'],
                            ['title' => 'Used in a control', 'text' => 'Documentation used in a control cannot be deleted. It can still be corrected; the control keeps what was registered. After «Register renewed» you can confirm the requirements again with the new edition.'],
                            ['title' => 'Expired and expiring soon', 'text' => 'Documentation with «Valid until» before today is shown as expired. If it expires within 60 days, it is shown under Needs follow-up. Without a date it has no expiry date.'],
                        ],
                    ],
                    [
                        'title' => 'Risk',
                        'items' => [
                            ['title' => 'Create risk', 'text' => 'When something can go wrong with the supplier, you create a risk in Risk. You choose the business area and describe the cause, event and consequence. The risk is assessed and treated there.'],
                            ['title' => 'What is shown here', 'text' => 'The supplier page shows the risks that concern the supplier and that you have access to yourself, with business area, status and risk level. Risks you do not have access to are not shown. Criticality does not affect the risk level.'],
                            ['title' => 'Link existing risk', 'text' => 'A risk already registered in Risk can be linked to the supplier. Whoever can edit the risk can remove the link again; the risk stays in Risk.'],
                        ],
                    ],
                    [
                        'title' => 'Earlier links to compliance requirements',
                        'items' => [
                            ['title' => 'What is shown here', 'text' => 'The «History» tab shows requirements in Compliance and audit that were earlier linked directly to the supplier, with reference, title and requirement source. Requirements you do not have access to are not shown. Such links can no longer be added or removed.'],
                            ['title' => 'No requirement status', 'text' => 'An earlier link does not say the requirement has been controlled, documented or met at the supplier. The supplier\'s control requirements are under «Requirements and qualifications», and the connection to Compliance and audit is shown as «Anchored in» on the control requirement.'],
                        ],
                    ],
                    [
                        'title' => 'Deviations and improvements',
                        'items' => [
                            ['title' => 'Follow up in Deviations and improvements', 'text' => 'When something at the supplier needs follow-up, you create a case in Deviations and improvements. You choose the case type, business area, responsible and deadline. The case is handled there, with actions, status and closing.'],
                            ['title' => 'What is shown here', 'text' => 'The supplier page shows the cases that concern the supplier and that you have access to yourself, with status and deadline. Cases you cannot access are not shown.'],
                            ['title' => 'Link an existing case', 'text' => 'A case already registered in Deviations and improvements can be linked to the supplier. Such a link can be removed again; a case created from here stays linked.'],
                        ],
                    ],
                    [
                        'title' => 'History',
                        'items' => [
                            ['title' => 'What is saved', 'text' => 'Every change to status, criticality and profile is saved with who made it, when and why, and is shown on the «History» tab. The history cannot be changed or deleted.'],
                        ],
                    ],
                    [
                        'title' => 'End or delete?',
                        'items' => [
                            ['title' => 'End', 'text' => 'The usual way to take a supplier out of use. The history is kept.'],
                            ['title' => 'Delete', 'text' => 'Only for a supplier registered by mistake that has never changed status or criticality, been assessed, had a profile, its own control requirements, controls, control decisions or due diligence assessments, had documentation registered or been linked to a case in Deviations and improvements, a risk in Risk or a requirement in Compliance and audit. Deleting cannot be undone.'],
                        ],
                    ],
                ],
            ],
            'import' => [
                'title' => 'About importing suppliers',
                'intro' => 'The import brings in an existing supplier register from Excel. Nothing is saved until you have checked the rows and confirmed.',
                'sections' => [
                    [
                        'title' => 'How it works',
                        'items' => [
                            ['title' => 'Upload', 'text' => 'Download the template, or use your own register. Columns are recognised by their header, in Norwegian or English.'],
                            ['title' => 'Check', 'text' => 'Every row is shown with its status and what the import will do. Correct errors in the file and upload it again if needed.'],
                            ['title' => 'Confirm', 'text' => 'The summary shows how many suppliers will be created, updated and skipped. The import starts only when you confirm, and it cannot run twice.'],
                        ],
                    ],
                    [
                        'title' => 'Duplicates',
                        'items' => [
                            ['title' => 'Organisation number', 'text' => 'The organisation number is the supplier\'s identity. If you already have the number, the row counts as an existing supplier and is not created again.'],
                            ['title' => 'No organisation number', 'text' => 'If the register already has a supplier with the same name, the row is skipped as a possible duplicate. The import never merges suppliers by name.'],
                            ['title' => 'Duplicate in the file', 'text' => 'If the same supplier appears several times in the file, only the first row is used.'],
                        ],
                    ],
                    [
                        'title' => 'Existing suppliers',
                        'items' => [
                            ['title' => 'Not changed unless you choose so', 'text' => 'By default, existing suppliers are skipped. If you choose to update them, only master data filled in in the file is changed, and you see the changes before confirming.'],
                            ['title' => 'Criticality and profile', 'text' => 'Status, criticality and supplier profile have their own history with a reason and are changed on the supplier page, not by an import.'],
                        ],
                    ],
                    [
                        'title' => 'What is stored',
                        'items' => [
                            ['title' => 'No file', 'text' => 'The Excel file itself is not stored. Only the values that can be imported are kept until you confirm, and they are deleted after a day if the import is not confirmed.'],
                            ['title' => 'Traceability', 'text' => 'New suppliers are registered with you as creator. The import records who carried it out, when, and what happened to each row.'],
                        ],
                    ],
                ],
            ],
            'deleted' => [
                'title' => 'About deleted suppliers',
                'intro_title' => 'What is this page for?',
                'intro' => 'This page shows which suppliers have been deleted, when it happened and who did it. It is read-only and documents the deletion afterwards.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Open the log', 'text' => 'Choose Governance → Suppliers in the left menu, then «Deleted suppliers» at the top right of the page.'],
                            ['title' => '2. Read the log', 'text' => 'Each line shows the supplier\'s name as it was when it was deleted, and «Deleted … by …» with the time and who deleted it. The most recent deletion comes first.'],
                            ['title' => '3. Go back', 'text' => 'Choose «To suppliers» to return to the register.'],
                        ],
                    ],
                    [
                        'title' => 'About the log',
                        'items' => [
                            ['title' => 'What is kept', 'text' => 'Only the name, the time and who deleted it. Only suppliers without history, assessments, documentation or controls can be deleted, so there is nothing more to keep.'],
                            ['title' => 'Cannot be changed', 'text' => 'The log cannot be changed or deleted, and a deleted supplier cannot be restored. Register it again if it is to be used.'],
                            ['title' => 'Access', 'text' => 'Only roles with the right to delete suppliers see the log. The right is managed under Customer environment → Permissions.'],
                        ],
                    ],
                ],
            ],
        ],
    ],
    'compliance' => [
        'module_name' => 'Compliance and audit',
        'help' => [
            'button' => 'Help',
            'purpose_heading' => 'What is this page for?',
            'index' => [
                'title' => 'About the requirement register',
                'intro' => 'The requirement register answers which requirements apply to the organisation – from activated standards and your own requirement sources. Each requirement shows its standard, clause and title, and its relevance or control selection. Whether the requirements are met is assessed under Compliance assessment.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Open a source', 'text' => 'The register opens in the «Grouped» view, with one row per requirement source, for example ISO 9001:2015. Choose the name of the source to open it. The number on the right shows how many requirements it holds.'],
                            ['title' => '2. Open a chapter', 'text' => 'Choose a chapter, for example chapter 4, to see its requirements. The controls in Annex A to ISO/IEC 27001 are split into their themes, A.5 to A.8. Your own sources without chapters list their requirements directly under the source.'],
                            ['title' => '3. Open a requirement', 'text' => 'Choose the requirement title to open the requirement page with its text, relevance and history. «Back to the requirement register» takes you back to the same view, with the same chapters open.'],
                            ['title' => '4. Switch view', 'text' => 'Choose «List» to see every requirement in one table, and «Grouped» to go back to sources and chapters.'],
                            ['title' => '5. Search across sources', 'text' => 'Type in «Search» and choose «Search». The hits are shown as a list from every source, with standard and clause, for example ISO 14001:2026 · 6.1.2 · Environmental aspects. Clear the search field and choose «Search» again to return to the view you had.'],
                            ['title' => '6. Use the filters', 'text' => 'Choose «Standard / source», «Status» or «Relevance / control selection» and choose «Search». The filters work in both views. In «Grouped» only sources and chapters with matches are shown, and the numbers count the matches. «Reset» removes the search and the filters.'],
                            ['title' => '7. Decide relevance and control selection', 'text' => 'Choose «Not decided / not selected» under «Relevance / control selection» and choose «Search» to find requirements waiting for a decision. Choose the requirement title and make the decision on the requirement page.'],
                            ['title' => '8. Move on to assessment', 'text' => 'Choose «Go to compliance assessment», or Compliance assessment in the menu at the top, to assess whether the requirements are met.'],
                            ['title' => '9. Register your own requirements', 'text' => 'Requirements that are not in the requirement library are registered with «New requirement». Create the source under «Requirement sources» first. The owner is optional.'],
                            ['title' => '10. Add more standards', 'text' => 'Choose «Add requirements from the library» to activate another standard.'],
                        ],
                    ],
                    [
                        'title' => 'Requirements and sources',
                        'items' => [
                            ['title' => 'Requirement', 'text' => 'A requirement is one thing the organisation must meet, for example a clause in a standard, an Annex A control, a section of a law or an obligation in a contract. It has a title and a requirement text.'],
                            ['title' => 'Requirement source', 'text' => 'Where the requirement comes from: an activated standard, a law or regulation, a contract, an internal requirement or something else. Your own sources are managed under Requirement sources on this page. A source can only be deleted while no requirement uses it.'],
                            ['title' => 'Reference', 'text' => 'The requirement\'s number or clause in the source, for example 6.1.2, A.8.13 or § 4-2. For your own requirements the reference is optional, but it must be unique within the same source.'],
                            ['title' => 'Origin', 'text' => 'Standard, edition, clause and title are shown together, for example ISO/IEC 27001:2022 · A.8.13 · Backup. When two standards have requirements with the same title, the origin tells them apart.'],
                        ],
                    ],
                    [
                        'title' => 'Relevance and control selection',
                        'items' => [
                            ['title' => 'Applies', 'text' => 'The requirement is part of the work and can be assessed. Mandatory requirements in a standard always apply.'],
                            ['title' => 'Not applicable', 'text' => 'A conditional requirement the organisation has determined does not apply, with a justification. It is not assessed for compliance and is not a gap.'],
                            ['title' => 'Not decided', 'text' => 'The relevance has not been decided yet. The requirement cannot be assessed for compliance until it applies.'],
                            ['title' => 'Control selection', 'text' => 'For the Annex A controls of ISO/IEC 27001 the choices are Included, Excluded and Not selected. An excluded control is not a gap.'],
                        ],
                    ],
                    [
                        'title' => 'Compliance and audits',
                        'items' => [
                            ['title' => 'Requirements and compliance', 'text' => 'The requirement register says which requirements apply. Whether the organisation meets them is assessed under Compliance assessment, where you also find the key figures.'],
                            ['title' => 'Requirements and audits', 'text' => 'A requirement says what the organisation must meet. An audit is a planned, systematic check of whether the requirements are actually complied with, with findings that can be followed up in Nonconformities and improvements.'],
                        ],
                    ],
                    [
                        'title' => 'The register',
                        'items' => [
                            ['title' => 'Active', 'text' => 'The requirement applies to the organisation. Active requirements are listed first, in the standard\'s order.'],
                            ['title' => 'Retired', 'text' => 'The requirement no longer applies, for example because the standard was replaced. It stays in the register with its history.'],
                            ['title' => 'Search and filter', 'text' => 'Search reference, title and requirement text, and filter by standard or source, relevance or control selection, and status. The search always covers every source.'],
                            ['title' => 'Grouped and List', 'text' => 'Both views show the same requirements. «Grouped» arranges them by source and chapter, «List» shows them in one table. No source or chapter is open the first time you come to the page.'],
                        ],
                    ],
                ],
            ],
            'requirement' => [
                'title' => 'About the requirement',
                'intro' => 'The requirement page shows one requirement with its origin, requirement text and guidance. Here you decide whether the requirement applies and assess whether it is met.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Read the requirement', 'text' => 'The origin at the top shows standard and clause. Read Requirement text. For requirements from the requirement library, From the requirement library also shows guidance, suggested documentation and links under Done in Procynia.'],
                            ['title' => '2. Decide whether it applies', 'text' => 'Under Relevance, choose «Change relevance», choose Applies or Not applicable and choose «Save relevance». Mandatory requirements already apply and cannot be set to Not applicable. For an Annex A control of ISO/IEC 27001 this is called Control selection: choose «Change control selection», Included or Excluded, and «Save control selection».'],
                            ['title' => '3. Justify the choice', 'text' => 'If you set a conditional requirement to Not applicable, you must fill in Justification. For an Annex A control both Included and Excluded must be justified, preferably with reference to the risk assessment.'],
                            ['title' => '4. Assess compliance', 'text' => 'Choose «Assess compliance» under Compliance and choose Result: Compliant, Partially compliant or Non-compliant. If you open the requirement with «Assess» from Compliance assessment, the form is already open. For requirements from the library the requirement must apply first, and an Annex A control must be Included. Not assessed is not a choice – it is what the requirement shows before its first assessment.'],
                            ['title' => '5. Justify and refer to documentation', 'text' => 'In Rationale, write what the assessment is based on and, for Partially compliant or Non-compliant, what is missing. Under «Documentation (optional)» refer to what the assessment relies on, for example a Wiki article, a document or a link – one per line. Choose «Save assessment». Who assessed and when is recorded automatically.'],
                            ['title' => '6. Go back', 'text' => 'Choose «Back to compliance assessment» to return to the list with the same filters, or «Back to the requirement register» if you came from there.'],
                            ['title' => '7. Follow up the gaps', 'text' => 'Requirements that are Partially compliant or Non-compliant are found under Compliance assessment. Actions are followed up as a case in Nonconformities and improvements, and the requirement can be taken into the scope of an audit. When the gaps are closed, register a new assessment.'],
                            ['title' => '8. Optional: owner and review', 'text' => 'Choose «Edit» to set «Owner (optional)» and Review interval, and choose «Save». Neither is needed to assess the requirement.'],
                            ['title' => '9. Optional: links to Quality', 'text' => 'Under «Links to Quality (optional)» you can choose «Add process» or «Add control». The links are additional information and do not replace the rationale and documentation of the assessment.'],
                        ],
                    ],
                    [
                        'title' => 'Ownership and follow-up',
                        'items' => [
                            ['title' => 'Owner', 'text' => 'Optional. A person who follows the requirement up over time. Otherwise responsibility follows the work: the assessment records who assessed, audits have their own owner, and cases in Nonconformities and improvements have their own owner. If the requirement has an owner, that person sees it under My tasks when it needs follow-up.'],
                            ['title' => 'Review interval', 'text' => 'How often the requirement should be reassessed: monthly, quarterly, half-yearly or yearly – or without a fixed interval.'],
                            ['title' => 'Assessed by', 'text' => 'Each assessment is saved with the name of the person who assessed and the time. The system sets it.'],
                        ],
                    ],
                    [
                        'title' => 'Compliance',
                        'items' => [
                            ['title' => 'Compliance assessment', 'text' => 'The organisation\'s own assessment of whether the requirement is met now, with result and rationale: Compliant, Partially compliant, Non-compliant or Not applicable. For requirements from the library only Compliant, Partially compliant or Non-compliant can be chosen – Not applicable is decided under Relevance. The latest assessment is the requirement\'s compliance today. Only active requirements can be assessed, and it requires the permission «Assess compliance».'],
                            ['title' => 'Not assessed', 'text' => 'Shown when the requirement has never been assessed. It is not a stored result, only the absence of an assessment.'],
                            ['title' => 'Documentation', 'text' => 'Optional references to what the assessment relies on. Links become clickable. The documentation is saved with the assessment and cannot be changed afterwards.'],
                            ['title' => 'Assessments cannot be changed', 'text' => 'An assessment is saved with date, assessor and rationale, and can be neither changed nor deleted. If an assessment is wrong, you correct it by registering a new one. The date is set by the system.'],
                            ['title' => 'Review interval', 'text' => 'The next assessment is calculated from the date of the latest assessment plus the interval. The day after the deadline, «Review overdue» is shown. Without an interval there is no fixed next assessment.'],
                            ['title' => 'The requirement has changed', 'text' => 'Each assessment keeps the requirement as it was: reference, title, requirement text and source. If the requirement changes afterwards, you are told. The assessment stands, but the requirement should be reassessed.'],
                        ],
                    ],
                    [
                        'title' => 'Links to Quality (optional)',
                        'items' => [
                            ['title' => 'What the links are', 'text' => 'Optional references to processes and controls in Quality that relate to the requirement. A process description is not in itself documentation that a requirement is met, and Procynia never asks for a link before a requirement can be assessed.'],
                            ['title' => 'Quality owns the processes and controls', 'text' => 'The processes and controls are created and changed in Quality. Only the link is stored here. Removing a link changes nothing in Quality.'],
                            ['title' => 'Evidence is only shown', 'text' => 'The evidence registered on a control in Quality is shown here as it is. It cannot be added, changed or removed from the requirement page.'],
                            ['title' => 'Evidence is not an assessment', 'text' => 'That a control has evidence does not automatically mean the requirement is met. Compliance must still be assessed explicitly under Compliance.'],
                            ['title' => 'Retired controls', 'text' => 'A control retired in Quality cannot be linked to new requirements. If it is already linked, the link stays and the control is marked as retired.'],
                            ['title' => 'Access', 'text' => 'You only see the section if you also have access to Quality. Access to Compliance and audit gives no insight into Quality.'],
                        ],
                    ],
                    [
                        'title' => 'Example: 9.3 Management review',
                        'items' => [
                            ['title' => 'The situation', 'text' => 'The organisation has held its management review and registered it in Management review in Procynia. You open the ISO 9001 requirement 9.3.3 Management review results.'],
                            ['title' => 'The assessment', 'text' => 'You compare the review with the requirement and the guidance: does it contain decisions on improvements, needed changes to the management system and resource needs – with owner and deadline?'],
                            ['title' => 'The result', 'text' => 'The review exists, but the decisions lack owner and deadline, and resource needs were not addressed. You choose Partially compliant, write in Rationale what is missing and refer to the minutes under Documentation. The gaps are followed up, for example as a case in Nonconformities and improvements.'],
                            ['title' => 'Documentation is not the same as compliant', 'text' => 'That the review is registered shows you have documentation. Whether the requirement is met depends on the content, and you decide that in the compliance assessment. Procynia never sets a requirement as compliant automatically.'],
                        ],
                    ],
                    [
                        'title' => 'Example: ISO/IEC 27001 A.8.13 Backup',
                        'items' => [
                            ['title' => 'The control selection', 'text' => 'The organisation stores customer data in cloud services, and the risk assessment shows loss of data is a significant risk. Under Control selection you choose Included and write in Justification that loss of customer data is a high risk in the risk assessment.'],
                            ['title' => 'The compliance', 'text' => 'You have a backup routine, but restore has never been tested. Under Compliance you choose Partially compliant, write that restore testing is missing and refer to the routine under Documentation.'],
                            ['title' => 'An excluded control', 'text' => 'If the organisation does not develop software itself, A.8.28 Secure coding can for example be set to Excluded with a justification. It is then not assessed for compliance and not counted as a gap, but the justification is part of the basis for the SoA.'],
                        ],
                    ],
                    [
                        'title' => 'Example: ISO 14001 6.1.2 Environmental aspects',
                        'items' => [
                            ['title' => 'The situation', 'text' => 'The organisation has a list of environmental aspects, but it only covers office operations. Transport to customers and waste from deliveries have not been considered.'],
                            ['title' => 'The assessment', 'text' => 'You read the requirement and the guidance: aspects are to be determined from a life cycle perspective, including abnormal conditions and emergencies, with criteria for significance. The list does not cover this, so you choose Partially compliant and write what is missing in Rationale.'],
                            ['title' => 'Further work', 'text' => 'When the significant environmental aspects are in place, you set environmental objectives for them (6.2.1). The objectives can be followed up in Objectives and KPIs if you have the module – the link under Done in Procynia shows the way. The link does not mean the requirement is met.'],
                        ],
                    ],
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Active', 'text' => 'The requirement applies and can be edited.'],
                            ['title' => 'Retired', 'text' => 'The requirement no longer applies. It cannot be edited until it is reopened. A reason is required.'],
                            ['title' => 'Reopen', 'text' => 'Makes a retired requirement active again. A reason is required.'],
                        ],
                    ],
                    [
                        'title' => 'Status history',
                        'items' => [
                            ['title' => 'Status history', 'text' => 'Every time the requirement is retired or reopened, who did it, when and why is saved. The history cannot be changed or deleted, and a requirement with history cannot be deleted.'],
                        ],
                    ],
                ],
            ],
            'assessments' => [
                'title' => 'About compliance assessment',
                'intro' => 'This is where the ongoing compliance work is done: which requirements have we assessed, which do we meet, and where do we have gaps? The list and the key figures cover every activated standard and your own requirement sources.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Choose a standard', 'text' => 'Choose a standard under «Standard», for example ISO 14001:2026, and choose «Filter». The key figures and the list then show only that standard. Choose «Reset» to see all.'],
                            ['title' => '2. Read the key figures', 'text' => 'Assessable requirements are the requirements that apply and can be assessed. Assessed is the sum of Compliant, Partially compliant and Non-compliant. Choose a figure to show those requirements in the list.'],
                            ['title' => '3. Find what is left', 'text' => 'Under «Show», choose for example «Not assessed» or «Gaps (partially or non-compliant)», and choose «Filter». You can also search for clause, title or requirement text.'],
                            ['title' => '4. Assess a requirement', 'text' => 'Choose «Assess» on the requirement. It opens with the form ready: choose Result, write Rationale, refer to documentation if you like and choose «Save assessment».'],
                            ['title' => '5. Go back', 'text' => 'Choose «Back to compliance assessment». You return to the list with the same filters, and the figures are updated.'],
                            ['title' => '6. Follow up the gaps', 'text' => 'Requirements with gaps are followed up as cases in Nonconformities and improvements. Choose Audit in the menu at the top when compliance is to be checked systematically.'],
                        ],
                    ],
                    [
                        'title' => 'The key figures',
                        'items' => [
                            ['title' => 'Assessable requirements', 'text' => 'Active requirements that apply and can be assessed: requirements that apply, included Annex A controls and your own requirements.'],
                            ['title' => 'Assessed', 'text' => 'The requirement has a compliance assessment, whatever the result. Assessed does not mean compliant.'],
                            ['title' => 'Compliant', 'text' => 'The latest assessment is Compliant.'],
                            ['title' => 'Partially compliant', 'text' => 'The latest assessment is Partially compliant. The rationale says what is missing.'],
                            ['title' => 'Non-compliant', 'text' => 'The latest assessment is Non-compliant.'],
                            ['title' => 'Not assessed', 'text' => 'The requirement applies but has no assessment yet.'],
                            ['title' => 'Review overdue', 'text' => 'The review interval has run out since the latest assessment. The result stands, but the requirement should be reassessed.'],
                        ],
                    ],
                    [
                        'title' => 'Outside the figures',
                        'items' => [
                            ['title' => 'Not applicable or excluded', 'text' => 'Requirements determined not applicable, and Annex A controls that are excluded. They are not gaps and are not assessed.'],
                            ['title' => 'Relevance or control selection not decided', 'text' => 'Requirements and controls waiting for a decision in the requirement register. They cannot be assessed until they apply or are included, and they are not counted as gaps.'],
                        ],
                    ],
                    [
                        'title' => 'Per standard',
                        'items' => [
                            ['title' => 'Counted once', 'text' => 'Each requirement belongs to one standard or source and is counted only there. The rows therefore add up to the figures for all standards together.'],
                            ['title' => 'Similar requirements', 'text' => 'When several standards have similar requirements, for example internal audit in both ISO 9001 and ISO 14001, they are separate requirements assessed one by one. The origin shows which standard a requirement comes from.'],
                        ],
                    ],
                    [
                        'title' => 'Assessment and audit',
                        'items' => [
                            ['title' => 'Compliance assessment', 'text' => 'The organisation\'s own assessment of whether a requirement is met.'],
                            ['title' => 'Audit', 'text' => 'A systematic check of compliance against criteria and objective evidence. Findings from an audit never change a compliance assessment by themselves – to change the assessment, register a new one.'],
                        ],
                    ],
                ],
            ],
            'audit_index' => [
                'title' => 'About audits',
                'intro' => 'Here you plan and follow up audits – planned reviews of whether the organisation actually complies with the requirements it has set itself or is subject to. An audit documents both what was examined and what, if anything, was found.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Create the audit', 'text' => 'Choose «New audit» and fill in «Title», «Type», «Responsible», «Auditor», «Planned start» and «Planned end».'],
                            ['title' => '2. State purpose and scope', 'text' => 'Write in «Purpose» why the audit is carried out, and in «Scope» what it covers. The scope can also be described by the requirements you choose alone.'],
                            ['title' => '3. Choose requirements', 'text' => 'Tick requirement sources under «Add from requirement source» to include every requirement that applies to the organisation, and any single requirements under «Choose single requirements». Choose «Save». Later you add more with «Add requirements» on the «Planning» tab.'],
                            ['title' => '4. Start the audit', 'text' => 'Choose «Start audit» when the planning is ready.'],
                            ['title' => '5. Record audit checks and documentation', 'text' => 'On the «Execution» tab choose «New audit check». Fill in «Audit check», «Observation» and «Documentation», tick «Relevant requirements» and choose «Save audit check». One audit check can concern several requirements.'],
                            ['title' => '6. Record any findings', 'text' => 'Choose «Record finding» on the audit check the finding comes from, or «New finding» under Findings. An audit without findings is just as well documented through its audit checks.'],
                            ['title' => '7. Complete with a conclusion', 'text' => 'Choose «Complete audit». The «Report and follow-up» tab shows the audit checks, the requirements examined, requirements without a documented examination and the findings. Write the «Conclusion» and choose «Complete audit».'],
                            ['title' => '8. Follow up nonconformities', 'text' => 'Choose «Follow up in Deviations & improvements» on the finding. The case shows which audit and which requirement it comes from.'],
                        ],
                    ],
                    [
                        'title' => 'What an audit is',
                        'items' => [
                            ['title' => 'Audit', 'text' => 'An audit is a planned and delimited review in which you check whether the organisation complies with the requirements in practice. It has a purpose, a scope, a responsible person, a planned period, audit checks and finally a conclusion.'],
                            ['title' => 'Purpose', 'text' => 'Why the audit is carried out, for example to verify that supplier management complies with the relevant requirements.'],
                            ['title' => 'Scope', 'text' => 'What the audit covers, for example the purchasing process and relevant requirements from ISO 9001 and ISO 27001. Describe it in text, choose requirements, or both.'],
                            ['title' => 'Internal', 'text' => 'An internal audit is carried out by the organisation itself, for example by an internal auditor or quality manager.'],
                            ['title' => 'External', 'text' => 'An external audit is carried out by someone outside the organisation, for example a certification body, a customer or a supervisory authority. The name of the auditor or audit firm can be entered in the Auditor field.'],
                            ['title' => 'Responsible', 'text' => 'The person in the organisation responsible for the audit, also when it is carried out by an external auditor. Only active people with access to Compliance and audit can be chosen.'],
                        ],
                    ],
                    [
                        'title' => 'Status',
                        'items' => [
                            ['title' => 'Planned', 'text' => 'The audit is registered but not started. Everything can still be changed.'],
                            ['title' => 'In progress', 'text' => 'The audit has started. Audit checks and findings are recorded, and purpose, scope, responsible person, auditor and conclusion can still be changed.'],
                            ['title' => 'Completed', 'text' => 'The audit is closed with a conclusion. It is locked and can only be changed after it has been reopened.'],
                            ['title' => 'Cancelled', 'text' => 'The audit was not carried out. It stays in the register with the reason, but cannot be changed.'],
                        ],
                    ],
                    [
                        'title' => 'Needs attention',
                        'items' => [
                            ['title' => 'What it means', 'text' => 'Needs attention means an audit has something concrete that should be followed up. The list at the top shows which audits and why, and each audit in the register shows the same reasons.'],
                            ['title' => 'Audit overdue', 'text' => 'The audit is planned or in progress, and the planned end has passed. The end date itself does not count as overdue.'],
                            ['title' => 'Nonconformity without follow-up', 'text' => 'The audit is completed, and at least one nonconformity has not been followed up in Deviations & improvements. Observations and improvement opportunities do not count.'],
                            ['title' => 'Calculated automatically', 'text' => 'The reasons are calculated automatically from the status, the planned end and the findings each time the page is opened. They are not stored statuses. When the nonconformity is followed up or the audit is completed, the reason disappears. Cancelled audits never need attention.'],
                        ],
                    ],
                    [
                        'title' => 'The register',
                        'items' => [
                            ['title' => 'Search and filter', 'text' => 'Search in title, purpose, scope and auditor, and filter by status and type. Audits in progress are shown first, then planned, completed and cancelled ones.'],
                            ['title' => 'Findings', 'text' => 'Audit findings – nonconformities, observations and improvement opportunities – are recorded on the audit page while the audit is in progress. Follow-up happens in Deviations & improvements.'],
                        ],
                    ],
                ],
            ],
            'audit' => [
                'title' => 'About the audit',
                'intro' => 'The audit page is where one audit is worked on: planning, execution and report. Here you document what was examined, what was found and what the audit concluded – also when it finds no nonconformities.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Create the audit', 'text' => 'Choose «New audit» and fill in «Title», «Type», «Responsible», «Auditor», «Planned start» and «Planned end».'],
                            ['title' => '2. State purpose and scope', 'text' => 'Write in «Purpose» why the audit is carried out, and in «Scope» what it covers. The scope can also be described by the requirements you choose alone.'],
                            ['title' => '3. Choose requirements', 'text' => 'Tick requirement sources under «Add from requirement source» to include every requirement that applies to the organisation, and any single requirements under «Choose single requirements». Choose «Save». Later you add more with «Add requirements» on the «Planning» tab.'],
                            ['title' => '4. Start the audit', 'text' => 'Choose «Start audit» when the planning is ready.'],
                            ['title' => '5. Record audit checks and documentation', 'text' => 'On the «Execution» tab choose «New audit check». Fill in «Audit check», «Observation» and «Documentation», tick «Relevant requirements» and choose «Save audit check». One audit check can concern several requirements.'],
                            ['title' => '6. Record any findings', 'text' => 'Choose «Record finding» on the audit check the finding comes from, or «New finding» under Findings. An audit without findings is just as well documented through its audit checks.'],
                            ['title' => '7. Complete with a conclusion', 'text' => 'Choose «Complete audit». The «Report and follow-up» tab shows the audit checks, the requirements examined, requirements without a documented examination and the findings. Write the «Conclusion» and choose «Complete audit».'],
                            ['title' => '8. Follow up nonconformities', 'text' => 'Choose «Follow up in Deviations & improvements» on the finding. The case shows which audit and which requirement it comes from.'],
                        ],
                    ],
                    [
                        'title' => 'Phases',
                        'items' => [
                            ['title' => 'Planning', 'text' => 'Purpose, scope, type, dates, responsible person and auditor, and the requirements and processes the audit covers.'],
                            ['title' => 'Execution', 'text' => 'What is to be checked, the audit checks that have been documented, and the findings.'],
                            ['title' => 'Report and follow-up', 'text' => 'An overview of examinations and findings, the conclusion and which findings have been followed up in Deviations & improvements.'],
                            ['title' => 'The phase follows the status', 'text' => 'The page opens in the phase the audit is in: Planned shows Planning, In progress shows Execution, and Completed shows Report and follow-up. You can open the other tabs at any time.'],
                        ],
                    ],
                    [
                        'title' => 'Scope',
                        'items' => [
                            ['title' => 'Scope', 'text' => 'The scope describes what the audit covers. It can be described in text, by the requirements in scope, or both – you do not need to write the same thing twice.'],
                            ['title' => 'Requirements in scope', 'text' => 'The requirements the audit will check, each with standard and clause, for example ISO 9001:2015 · 8.4. They are added as fixed rows: requirements added later are not included by themselves.'],
                            ['title' => 'From requirement source', 'text' => 'Adds every requirement in the source that applies to the organisation. Requirements determined not relevant, requirements whose relevance is open and Annex A controls that are not included are not added automatically. You can still choose them one by one if the audit should deliberately look at them – they are then marked in the scope.'],
                            ['title' => 'Retired', 'text' => 'A retired requirement can be in scope, for example when the audit looks at what used to apply. It is marked as retired and not removed automatically.'],
                            ['title' => 'Processes in scope', 'text' => 'The processes in Quality the audit looks at. The processes are owned by Quality; only the link is stored here. You see and link processes only if you also have access to Quality.'],
                        ],
                    ],
                    [
                        'title' => 'Audit checks',
                        'items' => [
                            ['title' => 'Audit check', 'text' => 'What the auditor examined, for example a review of supplier evaluations. It is recorded while the audit is in progress.'],
                            ['title' => 'Observation', 'text' => 'What the auditor actually examined and observed, for example how many evaluations were reviewed and who was interviewed.'],
                            ['title' => 'Documentation', 'text' => 'Optional references to documents, Wiki articles or other objective evidence.'],
                            ['title' => 'Relevant requirements', 'text' => 'One audit check can be linked to several requirements in scope, or to none, for example when an internal routine is examined. A requirement linked to an audit check cannot be removed from the scope until the link is removed.'],
                            ['title' => 'Examined is not met', 'text' => 'That a requirement has been examined does not mean it is met. The observations and the conclusion say what the audit found, and the audit never changes the compliance assessments.'],
                        ],
                    ],
                    [
                        'title' => 'Findings',
                        'items' => [
                            ['title' => 'Findings', 'text' => 'A finding is something the audit has found. It is recorded while the audit is in progress, with type, title, description and optionally the audit check it comes from and the requirement, process and control it concerns. Several findings can come from the same audit check.'],
                            ['title' => 'Nonconformity', 'text' => 'A requirement is not met. A nonconformity should be followed up in Deviations & improvements.'],
                            ['title' => 'Observation', 'text' => 'Something worth noting, but not a breach of a requirement. It may become a nonconformity if it is not followed up.'],
                            ['title' => 'Improvement opportunity', 'text' => 'Something works, but could be better.'],
                            ['title' => 'Findings are not actions', 'text' => 'A finding has no responsible person, deadline, status or action. Follow-up – responsibility, actions, deadlines and closing – happens in Deviations & improvements.'],
                            ['title' => 'Follow up in Deviations & improvements', 'text' => 'Creates a new case from the finding. It happens only when someone chooses it – never automatically. You choose the business area, responsible person and deadline; title and description are taken from the finding. A nonconformity becomes a deviation, observations and improvement opportunities an improvement. It can also be done after the audit is completed.'],
                            ['title' => 'Handed off', 'text' => 'A handed-off finding is locked for good, even if the audit is reopened, and cannot be deleted. The audit only shows that the finding has been handed off – not the status, actions or deadlines of the case.'],
                            ['title' => 'What you do not have access to', 'text' => 'Process and control are shown only if you have access to Quality. A case in a business area you do not have access to is only shown as Handed off – without a link and title.'],
                        ],
                    ],
                    [
                        'title' => 'Execution',
                        'items' => [
                            ['title' => 'Start audit', 'text' => 'Sets the audit from Planned to In progress. The type cannot be changed after the audit has started.'],
                            ['title' => 'Conclusion', 'text' => 'The overall assessment of the audit. It is written while the audit is in progress and must be filled in before the audit can be completed.'],
                            ['title' => 'Complete audit', 'text' => 'Closes the audit with the conclusion. An audit can be completed without findings, and without every requirement having its own audit check – the report shows which requirements lack a documented examination, so you can consider them. Afterwards the audit is locked, but findings that have not been handed off can still be followed up.'],
                            ['title' => 'Needs attention', 'text' => 'Shown under the title when the audit has passed its planned end without being completed, or is completed with nonconformities that have not been followed up. Calculated automatically and not stored.'],
                            ['title' => 'Cancel audit', 'text' => 'Used when the audit will not be carried out after all. A reason is required, and the audit remains as cancelled.'],
                            ['title' => 'Reopen audit', 'text' => 'Makes a completed audit editable again, for example to correct the conclusion. A reason is required, and the reopening is logged.'],
                        ],
                    ],
                    [
                        'title' => 'Status history',
                        'items' => [
                            ['title' => 'Status history', 'text' => 'Every status change is stored with who made it, when and any reason. The history cannot be changed or deleted, and an audit with history cannot be deleted – it is cancelled instead.'],
                        ],
                    ],
                ],
            ],
            'library' => [
                'title' => 'About the requirement library',
                'intro' => 'The requirement library is where you choose standards: ISO 9001 (quality), ISO/IEC 27001 (information security) and ISO 14001 (environment). Here you see what each standard contains and activate it for the organisation. The work itself is done in the Requirement register, Compliance assessment and Audit.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. See which standards exist', 'text' => 'Each standard has a card. The card shows whether the standard is «Activated» or «Not activated», and how many requirements it has.'],
                            ['title' => '2. Explore the contents', 'text' => 'Choose «View contents» to read the requirements, chapter by chapter, with guidance.'],
                            ['title' => '3. Activate a standard', 'text' => 'Choose «Activate for the organisation» on the card and confirm in the dialog. The requirements are added to the requirement register. It requires permission to edit requirements.'],
                            ['title' => '4. Move on to the register', 'text' => 'On an activated card, choose «Open in the requirement register» to see the requirements and decide relevance and control selection.'],
                            ['title' => '5. Assess compliance', 'text' => 'Choose «Go to compliance assessment» to assess the standard\'s requirements and see where you stand.'],
                        ],
                    ],
                    [
                        'title' => 'The workflow',
                        'items' => [
                            ['title' => 'Requirement library', 'text' => 'Choose and activate standards.'],
                            ['title' => 'Requirement register', 'text' => 'See which requirements apply, and decide relevance and control selection.'],
                            ['title' => 'Compliance assessment', 'text' => 'Assess whether the requirements are met, and follow the key figures.'],
                            ['title' => 'Audit', 'text' => 'Check compliance systematically and follow up findings.'],
                            ['title' => 'Move freely', 'text' => 'The menu at the top follows you through the whole module. The areas belong together, but you can move freely between them.'],
                        ],
                    ],
                    [
                        'title' => 'Requirement library and register',
                        'items' => [
                            ['title' => 'Requirement library', 'text' => 'Shows which standardised requirements exist. The library is maintained by Procynia and is the same for every organisation.'],
                            ['title' => 'Requirement register', 'text' => 'Shows which requirements apply to you. Requirements from an activated standard sit there together with requirements you have registered yourselves.'],
                            ['title' => 'Activate for the organisation', 'text' => 'Adds all the standard\'s requirements to the requirement register. It is done once. Later changes in the library update the requirement text automatically, but never change relevance, assessments or history.'],
                        ],
                    ],
                    [
                        'title' => 'The content',
                        'items' => [
                            ['title' => 'Edition', 'text' => 'Each requirement package covers one specific edition of the standard. A new edition becomes a package of its own, so requirements from different editions are never mixed.'],
                            ['title' => 'Own wording', 'text' => 'The standards are protected by copyright. The descriptions are Procynia\'s own short wording of what each clause requires – not the text of the standard. Use the standard itself as the basis for certification.'],
                            ['title' => 'Not professionally quality-assured', 'text' => 'Means the descriptions have not yet been checked against a licensed copy of the standard. The clause structure has been checked.'],
                        ],
                    ],
                ],
            ],
            'framework' => [
                'title' => 'About the requirement package',
                'intro' => 'The page shows all the requirements in the standard, ordered by chapter, with guidance for each. When the standard is activated, each requirement also shows its relevance or control selection in the requirement register.',
                'sections' => [
                    [
                        'title' => 'How to do it',
                        'items' => [
                            ['title' => '1. Move between chapters', 'text' => 'Choose a chapter to open it and see its clauses. «Expand all» and «Collapse all» open or close every chapter at once.'],
                            ['title' => '2. Read a requirement', 'text' => 'Choose «Show guidance» on the requirement. You see what the requirement involves, guidance, suggested documentation and, under Done in Procynia, where the work is typically done.'],
                            ['title' => '3. Search and filter', 'text' => 'Type in «Search the requirements» to search clause, title and description. When the standard is activated, you can choose under «Show» requirements whose relevance is not decided, or requirements that do not apply.'],
                            ['title' => '4. Activate from the Requirement library', 'text' => 'If the standard is Not activated, go back to the Requirement library and choose «Activate for the organisation» on the card. Mandatory requirements are set to Applies. Conditional requirements and the Annex A controls wait for you to decide relevance or control selection.'],
                            ['title' => '5. Work with the requirements', 'text' => 'Choose «Open requirement» to open one requirement, «Open in the requirement register» to see all of them in the register, or «Go to compliance assessment» to assess them and see status.'],
                        ],
                    ],
                    [
                        'title' => 'The requirements',
                        'items' => [
                            ['title' => 'Chapters and clauses', 'text' => 'Open a chapter to see its sub-clauses. Each requirement is assessed on its own.'],
                            ['title' => 'Requirement type', 'text' => 'Activity: the organisation must do something. Leadership responsibility: top management must demonstrate or ensure something. Documented information: the requirement concerns the documentation itself.'],
                            ['title' => 'Documented information', 'text' => 'Maintained means governing documents, such as procedures and policies. Retained means records as evidence, for example minutes and reports.'],
                            ['title' => 'Suggested documentation', 'text' => 'Examples of what is often used as evidence. The suggestions are not requirements in themselves.'],
                            ['title' => 'Done in Procynia', 'text' => 'Links to the modules where work on the requirement is typically done, for example Risk for risks and opportunities. The links are only shown for modules you have access to, and a link does not mean the requirement is met.'],
                        ],
                    ],
                    [
                        'title' => 'Relevance',
                        'items' => [
                            ['title' => 'Mandatory', 'text' => 'The requirement applies within the scope of the management system and cannot be determined not applicable.'],
                            ['title' => 'Conditional', 'text' => 'The requirement may be determined not applicable when it does not affect the ability or responsibility to deliver conforming products and services – for example design (8.3) if you only deliver to the customer\'s specification. A justification is required.'],
                            ['title' => 'Relevance and compliance', 'text' => 'Relevance decides whether the requirement is part of the work. Compliance assesses whether it is met. A requirement is never met by itself, not even when documentation is linked to it.'],
                        ],
                    ],
                    [
                        'title' => 'Annex A and the SoA (ISO/IEC 27001)',
                        'items' => [
                            ['title' => 'Two parts', 'text' => 'ISO/IEC 27001 has requirements for the management system itself in clauses 4–10. They always apply. Annex A is something else: a list of 93 security controls in four groups – organisational, people, physical and technological.'],
                            ['title' => 'Control selection', 'text' => 'The Annex A controls are not automatically requirements. Based on the risk assessment you choose for each control whether it is Included or Excluded, and justify the choice. Controls not yet decided are Not selected.'],
                            ['title' => 'Statement of Applicability (SoA)', 'text' => 'The SoA is the overview of which controls the organisation uses, why, whether they are implemented, and why others are excluded. The control selections with justifications and the compliance assessments in Procynia are the basis for it. Procynia does not produce the SoA document itself.'],
                            ['title' => 'Excluded is not a gap', 'text' => 'Under Compliance assessment, excluded controls and controls not yet selected are kept outside the key figures. Only included controls are assessed.'],
                        ],
                    ],
                ],
            ],
